    private FrozenDictionary<string, int>? _frozenIndex;
    private double[]? _prices;
    private int[]? _catIds;
    private string[]? _codesArray;

    public void AddProduct(string code, string category, decimal price)
    {
        if (!_categoryIdMap.TryGetValue(category, out int catId))
        {
            catId = _categoryNames.Count;
            _categoryIdMap[category] = catId;
            _categoryNames.Add(category);
        }

        int idx = _codes.Count;
        _indexBuilder[code] = idx;
        _codes.Add(code);
        _pricesList.Add((double)price);
        _catIdList.Add(catId);

        _frozenIndex = null; // invalidate cached structures
    }

