    public void Build()
    {
        _frozenIndex = _indexBuilder.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _prices = CollectionsMarshal.AsSpan(_pricesList).ToArray();
        _catIds = CollectionsMarshal.AsSpan(_catIdList).ToArray();
        _codesArray = CollectionsMarshal.AsSpan(_codes).ToArray();
    }

    private void EnsureBuilt()
    {
        if (_frozenIndex is null) Build();
