    {
        EnsureBuilt();
        return _frozenIndex!.TryGetValue(code, out int idx)
            ? _categoryNames[_catIds![idx]]
            : null;
    }

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        EnsureBuilt();
        var prices = _prices!;
        var frozen = _frozenIndex!;

        double total;
        if (codes is IList<string> list)
        {
            total = SumPricesFromList(list, frozen, prices);
        }
        else
        {
            total = 0;
            foreach (var code in codes)
            {
                if (frozen.TryGetValue(code, out int idx))
                    total += prices[idx];
            }
        }

        return (decimal)total;
    }

    private static double SumPricesFromList(
        IList<string> codes, FrozenDictionary<string, int> index, double[] prices)
    {
        int count = codes.Count;
        Span<double> buffer = count <= 256
            ? stackalloc double[count]
            : new double[count];

        int written = 0;
        for (int i = 0; i < count; i++)
        {
            if (index.TryGetValue(codes[i], out int idx))
                buffer[written++] = prices[idx];
        }

        return SimdSum(buffer[..written]);
    }

    /// <summary>SIMD-accelerated summation over a contiguous span of doubles.</summary>
    private static double SimdSum(ReadOnlySpan<double> values)
    {
        double total = 0;
        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<double>.Count)
        {
            var vSum = Vector<double>.Zero;
            var vectors = MemoryMarshal.Cast<double, Vector<double>>(values);

            for (int v = 0; v < vectors.Length; v++)
                vSum += vectors[v];

            total = Vector.Sum(vSum);
            i = vectors.Length * Vector<double>.Count;
        }

        for (; i < values.Length; i++)
            total += values[i];

        return total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        EnsureBuilt();

        if (!_categoryIdMap.TryGetValue(category, out int targetCatId))
            return new List<string>();

        var catIds = _catIds!;
        var codesArray = _codesArray!;
        var result = new List<string>();
        int i = 0;

        // SIMD-accelerated scan: compare category IDs in vectorized batches
        if (Vector.IsHardwareAccelerated && catIds.Length >= Vector<int>.Count)
        {
            var target = new Vector<int>(targetCatId);
            var vectors = MemoryMarshal.Cast<int, Vector<int>>(catIds.AsSpan());

            for (int v = 0; v < vectors.Length; v++)
            {
                var eq = Vector.Equals(vectors[v], target);
                if (eq != Vector<int>.Zero)
                {
                    int baseIdx = v * Vector<int>.Count;
                    for (int j = 0; j < Vector<int>.Count; j++)
                    {
                        if (eq[j] != 0)
                            result.Add(codesArray[baseIdx + j]);
                    }
                }
            }

            i = vectors.Length * Vector<int>.Count;
        }

        // Scalar tail
        for (; i < catIds.Length; i++)
        {
            if (catIds[i] == targetCatId)
                result.Add(codesArray[i]);
        }

        return result;
    }
